import React from 'react';
import CustomNav from '../CustomsNav';
import { userData } from '../../helpers';
import { useProducts } from './useProduct';

const Home = () => {
    const { username } = userData(); 
    const { categories, products } = useProducts();

    console.log('Categories:', categories);
    console.log('Products:', products);

    return (
        <div>
            <CustomNav />
            <div className='Home'>
                <h2 style={{ textAlign: "center" }}>Enjoy our sales!</h2>
                {
                    categories.length > 0 && categories.map(category => {
                        // Check if category.id exists in the product's category
                        const hasProduct = products.filter(product => 
                            product?.attributes?.category?.data?.id === category.id
                        );

                        console.log('Has Product:', hasProduct); // Check if any product matches the category

                        return hasProduct.length > 0 ? (
                            <div key={category.id}>
                                <h3>{category.name}</h3>
                                {/* Render products related to the category */}
                                <ul>
                                    {hasProduct.map(product => (
                                        <li key={product.id}>{product.attributes.name}</li>
                                    ))}
                                </ul>
                            </div>
                        ) : null;
                    })
                }
            </div>
        </div>
    );
};

export default Home;
